/**
 * Concept Extractor - 概念提取模块
 * 从综述论文中提取核心概念，分类并识别关系
 */

import { createAIProvider, type AIProvider } from '../../shared/ai-provider';
import { extractJson } from '../../shared/utils';
import { ApiInitializationError, getErrorMessage } from '../../shared/errors';
import type { PaperAnalysis } from '../../paper-analyzer/scripts/types';
import type {
  ExtractedConcept,
  ConceptRelation,
  ConceptTaxonomy,
  ConceptExtractionResult,
  ConceptExtractionOptions,
  ConceptCategory,
  MergedConcept,
  ConceptMergeResult
} from './types';

export default class ConceptExtractor {
  private ai: AIProvider | null = null;

  async initialize(): Promise<void> {
    if (!this.ai) {
      try {
        this.ai = await createAIProvider();
      } catch (error) {
        throw new ApiInitializationError(
          `Failed to initialize AI provider: ${getErrorMessage(error)}`,
          error instanceof Error ? error : undefined
        );
      }
    }
  }

  /**
   * 从论文分析结果中提取概念
   */
  async extractFromReview(
    analysis: PaperAnalysis,
    options: ConceptExtractionOptions = {}
  ): Promise<ConceptExtractionResult> {
    await this.initialize();

    const {
      minConcepts = 15,
      maxConcepts = 30,
      minImportance = 1,
      extractRelations = true
    } = options;

    // 提取概念
    const concepts = await this.extractConcepts(analysis, minConcepts, maxConcepts);

    // 过滤低重要性概念
    const filtered = concepts.filter(c => c.importance >= minImportance);

    // 提取关系
    let relations: ConceptRelation[] = [];
    if (extractRelations && filtered.length > 1) {
      relations = await this.extractRelations(filtered);
    }

    // 构建分类体系
    const taxonomy = this.buildTaxonomy(filtered);

    // 统计信息
    const byCategory: Record<ConceptCategory, number> = {
      foundation: 0, core: 0, advanced: 0, application: 0
    };
    const byImportance: Record<number, number> = {};
    for (const c of filtered) {
      byCategory[c.category]++;
      byImportance[c.importance] = (byImportance[c.importance] || 0) + 1;
    }

    return {
      sourceTitle: analysis.metadata.title,
      sourceUrl: analysis.metadata.url,
      concepts: filtered,
      relations,
      taxonomy,
      stats: {
        totalConcepts: filtered.length,
        byCategory,
        byImportance
      }
    };
  }

  /**
   * 使用AI提取概念
   */
  private async extractConcepts(
    analysis: PaperAnalysis,
    min: number,
    max: number
  ): Promise<ExtractedConcept[]> {
    const prompt = `从以下论文分析中提取${min}-${max}个核心学术概念。

论文标题: ${analysis.metadata.title}
关键词: ${analysis.metadata.keywords.join(', ')}
摘要: ${analysis.abstract}
要点: ${analysis.keyPoints.map(kp => kp.point).join('; ')}
贡献: ${analysis.contributions.map(c => c.description).join('; ')}

请提取核心概念并返回JSON格式:
{
  "concepts": [
    {
      "name": "概念名称",
      "nameEn": "English Name",
      "nameZh": "中文名称",
      "category": "foundation|core|advanced|application",
      "importance": 1-5,
      "definition": "简短定义",
      "frequency": "high|medium|low",
      "aliases": ["别名1", "别名2"]
    }
  ]
}

分类标准:
- foundation: 基础理论概念（如线性代数、概率论）
- core: 核心技术概念（如注意力机制、Transformer）
- advanced: 进阶概念（如多头注意力、位置编码）
- application: 应用概念（如机器翻译、文本生成）

重要性标准:
- 5: 论文核心主题
- 4: 论文重要组成部分
- 3: 论文中频繁提及
- 2: 论文中有涉及
- 1: 论文中偶尔提到`;

    const responseText = await this.ai!.chat([
      { role: 'system', content: '你是学术概念提取专家。只返回JSON格式。' },
      { role: 'user', content: prompt }
    ], { temperature: 0.2 });

    const result = extractJson<{
      concepts?: Array<{
        name: string;
        nameEn?: string;
        nameZh?: string;
        category?: string;
        importance?: number;
        definition?: string;
        frequency?: string;
        aliases?: string[];
      }>;
    }>(responseText);

    if (!result.success || !result.data?.concepts) {
      console.error('Failed to extract concepts:', result.error);
      return [];
    }

    return result.data.concepts.map((c, index) => ({
      id: `concept_${index}`,
      name: c.name,
      nameEn: c.nameEn,
      nameZh: c.nameZh,
      category: this.validateCategory(c.category),
      importance: Math.min(5, Math.max(1, c.importance || 3)),
      definition: c.definition || '',
      frequency: this.validateFrequency(c.frequency),
      relatedConcepts: [],
      aliases: c.aliases || []
    }));
  }

  /**
   * 提取概念间关系
   */
  private async extractRelations(concepts: ExtractedConcept[]): Promise<ConceptRelation[]> {
    const conceptNames = concepts.map(c => c.name).join(', ');

    const prompt = `分析以下概念之间的关系:

概念列表: ${conceptNames}

请返回JSON格式的关系列表:
{
  "relations": [
    {
      "source": "源概念名称",
      "target": "目标概念名称",
      "relationType": "prerequisite|related|derived|component|contrast",
      "strength": 0.0-1.0,
      "description": "关系描述"
    }
  ]
}

关系类型说明:
- prerequisite: 前置依赖关系
- related: 相关关系
- derived: 衍生关系
- component: 组成部分
- contrast: 对比关系`;

    const responseText = await this.ai!.chat([
      { role: 'system', content: '你是学术概念关系分析专家。只返回JSON格式。' },
      { role: 'user', content: prompt }
    ], { temperature: 0.2 });

    const result = extractJson<{
      relations?: Array<{
        source: string;
        target: string;
        relationType?: string;
        strength?: number;
        description?: string;
      }>;
    }>(responseText);

    if (!result.success || !result.data?.relations) {
      return [];
    }

    return result.data.relations
      .map(r => {
        const sourceConcept = concepts.find(c =>
          c.name === r.source || c.nameEn === r.source || c.nameZh === r.source
        );
        const targetConcept = concepts.find(c =>
          c.name === r.target || c.nameEn === r.target || c.nameZh === r.target
        );

        if (!sourceConcept || !targetConcept) return null;

        return {
          sourceId: sourceConcept.id,
          targetId: targetConcept.id,
          relationType: this.validateRelationType(r.relationType),
          strength: Math.min(1, Math.max(0, r.strength || 0.5)),
          description: r.description
        };
      })
      .filter((r): r is ConceptRelation => r !== null);
  }

  /**
   * 构建概念分类体系
   */
  private buildTaxonomy(concepts: ExtractedConcept[]): ConceptTaxonomy {
    return {
      foundation: concepts.filter(c => c.category === 'foundation'),
      core: concepts.filter(c => c.category === 'core'),
      advanced: concepts.filter(c => c.category === 'advanced'),
      application: concepts.filter(c => c.category === 'application')
    };
  }

  /**
   * 合并多个提取结果（去重）
   */
  mergeConcepts(results: ConceptExtractionResult[]): ConceptMergeResult {
    const conceptMap = new Map<string, MergedConcept>();
    const allRelations: ConceptRelation[] = [];
    let totalBefore = 0;

    for (const result of results) {
      totalBefore += result.concepts.length;

      for (const concept of result.concepts) {
        const key = this.normalizeConceptName(concept.name);
        const existing = conceptMap.get(key);

        if (existing) {
          // 合并已存在的概念
          existing.sources.push(result.sourceTitle);
          existing.occurrenceCount++;
          existing.mergedImportance = Math.max(existing.mergedImportance, concept.importance);
          // 合并别名
          for (const alias of concept.aliases) {
            if (!existing.aliases.includes(alias)) {
              existing.aliases.push(alias);
            }
          }
        } else {
          conceptMap.set(key, {
            ...concept,
            id: `merged_${conceptMap.size}`,
            sources: [result.sourceTitle],
            mergedImportance: concept.importance,
            occurrenceCount: 1
          });
        }
      }

      allRelations.push(...result.relations);
    }

    const mergedConcepts = Array.from(conceptMap.values());

    // 更新关系中的概念ID
    const nameToId = new Map<string, string>();
    for (const c of mergedConcepts) {
      nameToId.set(this.normalizeConceptName(c.name), c.id);
      for (const alias of c.aliases) {
        nameToId.set(this.normalizeConceptName(alias), c.id);
      }
    }

    // 去重关系
    const relationSet = new Set<string>();
    const dedupedRelations: ConceptRelation[] = [];
    for (const r of allRelations) {
      const key = `${r.sourceId}-${r.targetId}-${r.relationType}`;
      if (!relationSet.has(key)) {
        relationSet.add(key);
        dedupedRelations.push(r);
      }
    }

    return {
      concepts: mergedConcepts,
      relations: dedupedRelations,
      stats: {
        totalBefore,
        totalAfter: mergedConcepts.length,
        duplicatesRemoved: totalBefore - mergedConcepts.length,
        sourcesCount: results.length
      }
    };
  }

  /**
   * 标准化概念名称用于去重
   */
  private normalizeConceptName(name: string): string {
    return name.toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]/g, '').trim();
  }

  private validateCategory(category?: string): ConceptCategory {
    const valid: ConceptCategory[] = ['foundation', 'core', 'advanced', 'application'];
    return valid.includes(category as ConceptCategory) ? category as ConceptCategory : 'core';
  }

  private validateFrequency(freq?: string): 'high' | 'medium' | 'low' {
    const valid = ['high', 'medium', 'low'];
    return valid.includes(freq as string) ? freq as 'high' | 'medium' | 'low' : 'medium';
  }

  private validateRelationType(type?: string): ConceptRelation['relationType'] {
    const valid = ['prerequisite', 'related', 'derived', 'component', 'contrast'];
    return valid.includes(type as string) ? type as ConceptRelation['relationType'] : 'related';
  }

  /**
   * 格式化概念提取结果
   */
  formatResult(result: ConceptExtractionResult): string {
    const lines: string[] = [
      `📚 概念提取结果 - ${result.sourceTitle}\n`,
      `📊 统计: ${result.stats.totalConcepts} 个概念\n`
    ];

    const categoryLabels: Record<ConceptCategory, string> = {
      foundation: '🔹 基础概念',
      core: '🔸 核心概念',
      advanced: '🔶 进阶概念',
      application: '🔷 应用概念'
    };

    for (const [category, label] of Object.entries(categoryLabels)) {
      const concepts = result.taxonomy[category as keyof ConceptTaxonomy];
      if (concepts.length > 0) {
        lines.push(`\n${label} (${concepts.length}):`);
        for (const c of concepts) {
          const stars = '★'.repeat(c.importance) + '☆'.repeat(5 - c.importance);
          lines.push(`  ${stars} ${c.name}${c.nameEn ? ` (${c.nameEn})` : ''}`);
          if (c.definition) {
            lines.push(`       ${c.definition}`);
          }
        }
      }
    }

    if (result.relations.length > 0) {
      lines.push(`\n🔗 概念关系 (${result.relations.length}):`);
      for (const r of result.relations.slice(0, 15)) {
        const source = result.concepts.find(c => c.id === r.sourceId);
        const target = result.concepts.find(c => c.id === r.targetId);
        if (source && target) {
          lines.push(`  ${source.name} --[${r.relationType}]--> ${target.name}`);
        }
      }
    }

    return lines.join('\n');
  }
}

/**
 * Concept Extractor - Type Definitions
 * 概念提取模块类型定义
 */

/**
 * 概念类别
 */
export type ConceptCategory = 'foundation' | 'core' | 'advanced' | 'application';

/**
 * 提取的概念
 */
export interface ExtractedConcept {
  /** 概念ID */
  id: string;
  /** 概念名称 */
  name: string;
  /** 英文名 */
  nameEn?: string;
  /** 中文名 */
  nameZh?: string;
  /** 概念类别 */
  category: ConceptCategory;
  /** 重要性评分 (1-5) */
  importance: number;
  /** 概念定义 */
  definition: string;
  /** 在综述中的出现频率估计 */
  frequency: 'high' | 'medium' | 'low';
  /** 相关概念ID列表 */
  relatedConcepts: string[];
  /** 关键词/别名 */
  aliases: string[];
}

/**
 * 概念间关系
 */
export interface ConceptRelation {
  /** 源概念ID */
  sourceId: string;
  /** 目标概念ID */
  targetId: string;
  /** 关系类型 */
  relationType: 'prerequisite' | 'related' | 'derived' | 'component' | 'contrast';
  /** 关系强度 (0-1) */
  strength: number;
  /** 关系描述 */
  description?: string;
}

/**
 * 概念分类体系
 */
export interface ConceptTaxonomy {
  /** 基础概念 */
  foundation: ExtractedConcept[];
  /** 核心概念 */
  core: ExtractedConcept[];
  /** 进阶概念 */
  advanced: ExtractedConcept[];
  /** 应用概念 */
  application: ExtractedConcept[];
}

/**
 * 概念提取结果
 */
export interface ConceptExtractionResult {
  /** 提取来源论文标题 */
  sourceTitle: string;
  /** 提取来源URL */
  sourceUrl: string;
  /** 提取的所有概念 */
  concepts: ExtractedConcept[];
  /** 概念间关系 */
  relations: ConceptRelation[];
  /** 概念分类体系 */
  taxonomy: ConceptTaxonomy;
  /** 统计信息 */
  stats: {
    totalConcepts: number;
    byCategory: Record<ConceptCategory, number>;
    byImportance: Record<number, number>;
  };
}

/**
 * 概念提取选项
 */
export interface ConceptExtractionOptions {
  /** 提取概念数量范围 */
  minConcepts?: number;
  maxConcepts?: number;
  /** 最小重要性 */
  minImportance?: number;
  /** 语言偏好 */
  language?: 'zh-CN' | 'en';
  /** 是否提取关系 */
  extractRelations?: boolean;
}

/**
 * 合并后的概念（多综述去重后） */
export interface MergedConcept extends ExtractedConcept {
  /** 来源综述列表 */
  sources: string[];
  /** 合并后的综合重要性 */
  mergedImportance: number;
  /** 出现次数 */
  occurrenceCount: number;
}

/**
 * 概念合并结果
 */
export interface ConceptMergeResult {
  /** 合并后的概念列表 */
  concepts: MergedConcept[];
  /** 合并后的关系列表 */
  relations: ConceptRelation[];
  /** 合并统计 */
  stats: {
    totalBefore: number;
    totalAfter: number;
    duplicatesRemoved: number;
    sourcesCount: number;
  };
}

/**
 * Concept Learner - Core Module
 * 概念学习核心模块
 *
 * 帮助用户快速构建知识框架：
 * - 概念定义与解释
 * - 核心组成要素
 * - 历史演进
 * - 应用场景
 * - 相关概念
 * - 学习路径
 */

import { createAIProvider, type AIProvider } from '../../shared/ai-provider';
import { extractJson } from '../../shared/utils';
import { ApiInitializationError, getErrorMessage } from '../../shared/errors';
import type { WebSearchResultItem } from '../../shared/types';
import type { LearnOptions, ConceptCard, ComparisonResult, LearningPathPlan, Paper, CodeExample } from './types';

export default class ConceptLearner {
  private ai: AIProvider | null = null;

  async initialize(): Promise<void> {
    if (!this.ai) {
      try {
        this.ai = await createAIProvider();
      } catch (error) {
        throw new ApiInitializationError(
          `Failed to initialize AI provider: ${getErrorMessage(error)}`,
          error instanceof Error ? error : undefined
        );
      }
    }
  }

  /**
   * 学习一个概念
   */
  async learn(concept: string, options: LearnOptions = {}): Promise<ConceptCard> {
    await this.initialize();

    const {
      depth = 'intermediate',
      includePapers = true,
      includeCode = false,
      language = 'zh-CN',
      focusAreas
    } = options;

    // 获取概念基础信息
    const basicInfo = await this.fetchConceptBasics(concept, language);

    // 获取相关论文
    let keyPapers: Paper[] = [];
    if (includePapers) {
      keyPapers = await this.fetchKeyPapers(concept);
    }

    // 获取代码示例
    let codeExamples: CodeExample[] = [];
    if (includeCode) {
      codeExamples = await this.fetchCodeExamples(concept);
    }

    // 生成学习路径
    const learningPath = await this.generateLearningPath(concept, depth, language);

    // 组装概念卡片
    const card: ConceptCard = {
      concept,
      ...basicInfo,
      learningPath,
      keyPapers,
      codeExamples,
      generatedAt: new Date().toISOString()
    };

    return card;
  }

  /**
   * 获取概念基础信息
   */
  private async fetchConceptBasics(concept: string, language: string): Promise<Partial<ConceptCard>> {
    const langPrompt = language === 'zh-CN'
      ? '请用中文回答'
      : 'Please answer in English';

    const prompt = `${langPrompt}

请为概念"${concept}"生成一份详细的知识卡片，包含以下内容：

1. **定义**: 给出清晰的定义，包括一句话简洁解释
2. **核心组成**: 列出3-5个核心组成部分，每个说明其作用和重要性
3. **历史演进**: 说明概念的起源、关键发展节点、当前状态
4. **应用场景**: 列出主要应用领域和具体案例
5. **相关概念**: 列出相关概念，区分前置知识、相关知识、衍生概念、替代方案

请以JSON格式返回，结构如下：
{
  "definition": "详细定义",
  "shortExplanation": "一句话解释",
  "coreComponents": [
    {"name": "组成名称", "description": "描述", "importance": "high|medium|low"}
  ],
  "history": {
    "origin": "起源背景",
    "keyDevelopments": [
      {"year": "年份", "event": "事件", "significance": "意义"}
    ],
    "currentStatus": "当前状态"
  },
  "applications": [
    {"domain": "领域", "examples": ["案例1", "案例2"], "impact": "影响"}
  ],
  "relatedConcepts": [
    {"concept": "概念名", "relationship": "prerequisite|related|derived|alternative", "briefExplanation": "简要说明"}
  ],
  "resources": [
    {"type": "paper|tutorial|course|book|code", "title": "标题", "url": "链接", "description": "描述", "difficulty": "beginner|intermediate|advanced"}
  ]
}`;

    const responseText = await this.ai!.chat([
      { role: 'system', content: '你是一位知识结构化专家，擅长将复杂概念转化为清晰的学习框架。' },
      { role: 'user', content: prompt }
    ], { temperature: 0.3 });

    // 使用改进的 JSON 提取
    const result = extractJson<Partial<ConceptCard>>(responseText);

    if (result.success && result.data) {
      return result.data;
    }

    console.error('Failed to parse concept response:', result.error);
    return {
      definition: responseText,
      shortExplanation: '',
      coreComponents: [],
      history: { origin: '', keyDevelopments: [], currentStatus: '' },
      applications: [],
      relatedConcepts: [],
      resources: []
    };
  }

  /**
   * 获取关键论文
   */
  private async fetchKeyPapers(concept: string): Promise<Paper[]> {
    try {
      // 优先使用 Semantic Scholar API
      const papers = await this.searchSemanticScholar(concept);
      if (papers.length > 0) {
        return papers;
      }

      // 回退到 web search（如果可用）
      if (this.ai!.webSearch) {
        const results: WebSearchResultItem[] = await this.ai!.webSearch(
          `${concept} paper arxiv research`,
          5
        );

        return results.slice(0, 5).map((item) => ({
          title: item.name,
          authors: [],
          year: item.date?.split('-')[0] || '',
          url: item.url,
          summary: item.snippet || ''
        }));
      }

      console.warn('No paper search method available');
      return [];
    } catch (error) {
      console.error('Failed to fetch papers:', getErrorMessage(error));
      return [];
    }
  }

  /**
   * 从 Semantic Scholar 搜索论文
   */
  private async searchSemanticScholar(concept: string): Promise<Paper[]> {
    try {
      const fields = 'paperId,title,abstract,authors,year,citationCount,venue,url';
      const url = `https://api.semanticscholar.org/graph/v1/paper/search?query=${encodeURIComponent(concept)}&limit=5&fields=${fields}`;

      const response = await fetch(url);
      if (!response.ok) {
        console.warn(`Semantic Scholar API error: ${response.status}`);
        return [];
      }

      const data = await response.json() as {
        data?: Array<{
          paperId: string;
          title: string;
          abstract?: string;
          authors?: Array<{ name: string }>;
          year?: number;
          citationCount?: number;
          venue?: string;
          url?: string;
        }>;
      };

      if (!data.data) return [];

      return data.data.map(paper => ({
        title: paper.title,
        authors: paper.authors?.map(a => a.name) || [],
        year: paper.year?.toString() || '',
        url: paper.url || `https://www.semanticscholar.org/paper/${paper.paperId}`,
        summary: paper.abstract?.substring(0, 200) + '...' || ''
      }));
    } catch (error) {
      console.error('Semantic Scholar search error:', getErrorMessage(error));
      return [];
    }
  }

  /**
   * 获取代码示例
   */
  private async fetchCodeExamples(concept: string): Promise<CodeExample[]> {
    const prompt = `为概念"${concept}"生成1-2个简洁的代码示例，帮助理解其实现原理。

返回JSON格式：
{
  "examples": [
    {
      "title": "示例标题",
      "description": "说明这个示例展示什么",
      "language": "python|javascript|etc",
      "code": "代码内容"
    }
  ]
}`;

    try {
      const responseText = await this.ai!.chat([
        { role: 'system', content: '你是一位代码教学专家，擅长用简洁的代码说明复杂概念。' },
        { role: 'user', content: prompt }
      ], { temperature: 0.2 });

      const result = extractJson<{ examples?: CodeExample[] }>(responseText);

      if (result.success && result.data?.examples) {
        return result.data.examples;
      }
    } catch (error) {
      console.error('Failed to generate code examples:', getErrorMessage(error));
    }

    return [];
  }

  /**
   * 生成学习路径
   */
  private async generateLearningPath(
    concept: string,
    depth: string,
    language: string
  ): Promise<ConceptCard['learningPath']> {
    const langPrompt = language === 'zh-CN' ? '请用中文回答' : 'Please answer in English';

    const prompt = `${langPrompt}

为学习"${concept}"设计一条从入门到${depth === 'advanced' ? '精通' : '进阶'}的学习路径。

返回JSON格式：
{
  "stages": [
    {
      "stage": "阶段名称（如：基础概念）",
      "concepts": ["需要学习的概念1", "概念2"],
      "estimatedTime": "预计时间",
      "resources": ["推荐资源1", "资源2"]
    }
  ]
}`;

    try {
      const responseText = await this.ai!.chat([
        { role: 'system', content: '你是一位学习路径规划专家。' },
        { role: 'user', content: prompt }
      ], { temperature: 0.3 });

      const result = extractJson<{ stages?: ConceptCard['learningPath'] }>(responseText);

      if (result.success && result.data?.stages) {
        return result.data.stages;
      }
    } catch (error) {
      console.error('Failed to generate learning path:', getErrorMessage(error));
    }

    return [];
  }

  /**
   * 对比两个概念
   */
  async compare(concept1: string, concept2: string, language: string = 'zh-CN'): Promise<ComparisonResult> {
    await this.initialize();

    const langPrompt = language === 'zh-CN' ? '请用中文回答' : 'Please answer in English';

    const prompt = `${langPrompt}

对比分析"${concept1}"和"${concept2}"两个概念：

返回JSON格式：
{
  "similarities": ["相似点1", "相似点2"],
  "differences": ["差异点1", "差异点2"],
  "useCases": {
    "preferConcept1": ["适合使用${concept1}的场景"],
    "preferConcept2": ["适合使用${concept2}的场景"]
  }
}`;

    const responseText = await this.ai!.chat([
      { role: 'system', content: '你是一位技术对比分析专家。' },
      { role: 'user', content: prompt }
    ], { temperature: 0.2 });

    const result = extractJson<{
      similarities?: string[];
      differences?: string[];
      useCases?: { preferConcept1?: string[]; preferConcept2?: string[] };
    }>(responseText);

    if (result.success && result.data) {
      return {
        concept1,
        concept2,
        similarities: result.data.similarities || [],
        differences: result.data.differences || [],
        useCases: {
          preferConcept1: result.data.useCases?.preferConcept1 || [],
          preferConcept2: result.data.useCases?.preferConcept2 || []
        }
      };
    }

    return {
      concept1,
      concept2,
      similarities: [],
      differences: [],
      useCases: { preferConcept1: [], preferConcept2: [] }
    };
  }

  /**
   * 规划学习路径
   */
  async planLearningPath(
    topic: string,
    options: {
      currentLevel: string;
      targetLevel: string;
      timeCommitment: string;
    }
  ): Promise<LearningPathPlan> {
    await this.initialize();

    const { currentLevel, targetLevel, timeCommitment } = options;

    const prompt = `为学习主题"${topic}"规划学习路径：

当前水平：${currentLevel}
目标水平：${targetLevel}
可用时间：${timeCommitment}

返回JSON格式：
{
  "topic": "${topic}",
  "currentLevel": "${currentLevel}",
  "targetLevel": "${targetLevel}",
  "estimatedDuration": "总预计时长",
  "stages": [
    {
      "stage": "阶段名",
      "concepts": ["概念"],
      "estimatedTime": "时间",
      "resources": ["资源"]
    }
  ],
  "milestones": ["里程碑1", "里程碑2"],
  "recommendedOrder": ["建议学习顺序"]
}`;

    const responseText = await this.ai!.chat([
      { role: 'system', content: '你是一位学习路径规划专家。' },
      { role: 'user', content: prompt }
    ], { temperature: 0.3 });

    const result = extractJson<LearningPathPlan>(responseText);

    if (result.success && result.data) {
      return result.data;
    }

    return {
      topic,
      currentLevel,
      targetLevel,
      estimatedDuration: '',
      stages: [],
      milestones: [],
      recommendedOrder: []
    };
  }

