/**
 * Shared Utils - 公共工具函数
 * 提供 XML 解析、JSON 提取、重试机制、超时控制等
 */

import type { ParsedArxivEntry, RetryOptions, JsonExtractionResult } from './types';
import { TimeoutError, ParseError, ApiCallError, isRetryableError, getErrorMessage } from './errors';

// 默认重试配置
const DEFAULT_RETRY_OPTIONS: Required<RetryOptions> = {
  maxRetries: 3,
  initialDelayMs: 1000,
  maxDelayMs: 10000,
  backoffMultiplier: 2,
  retryableErrors: ['ECONNRESET', 'ETIMEDOUT', 'ECONNREFUSED', 'rate limit', '429', '503']
};

// 默认超时时间
const DEFAULT_TIMEOUT_MS = 30000;

/**
 * 解析 arXiv XML 响应
 * 使用 DOMParser 替代正则表达式，更安全可靠
 */
export function parseArxivXml(xml: string): ParsedArxivEntry[] {
  const results: ParsedArxivEntry[] = [];

  try {
    // 在 Node/Bun 环境中使用简单的 XML 解析
    // 由于 DOMParser 在 Node 中不可用，使用改进的正则解析
    const entries = xml.split('<entry>').slice(1);

    for (const entry of entries) {
      try {
        const id = extractXmlTag(entry, 'id');
        const title = extractXmlTag(entry, 'title').replace(/\s+/g, ' ').trim();
        const abstract = extractXmlTag(entry, 'summary').replace(/\s+/g, ' ').trim();
        const published = extractXmlTag(entry, 'published');
        const updated = extractXmlTag(entry, 'updated');

        // 提取作者 - 改进的解析
        const authors: string[] = [];
        const authorRegex = /<author>[\s\S]*?<name>([^<]+)<\/name>[\s\S]*?<\/author>/g;
        let authorMatch;
        while ((authorMatch = authorRegex.exec(entry)) !== null) {
          const name = authorMatch[1].trim();
          if (name) {
            authors.push(name);
          }
        }

        // 提取分类
        const categories: string[] = [];
        const categoryRegex = /category\s+term="([^"]+)"/g;
        let categoryMatch;
        while ((categoryMatch = categoryRegex.exec(entry)) !== null) {
          categories.push(categoryMatch[1]);
        }

        // 提取 PDF URL
        const pdfLinkMatch = entry.match(/<link[^>]*title="pdf"[^>]*href="([^"]+)"/);
        const pdfUrl = pdfLinkMatch ? pdfLinkMatch[1] : id.replace('/abs/', '/pdf/') + '.pdf';

        // 提取 arXiv ID
        const arxivId = id.split('/abs/')[1] || id;

        results.push({
          id: arxivId,
          title,
          authors,
          abstract,
          published: published.split('T')[0],
          updated: updated ? updated.split('T')[0] : undefined,
          categories,
          pdfUrl
        });
      } catch (e) {
        // 跳过解析失败的条目
        continue;
      }
    }
  } catch (error) {
    throw new ParseError('Failed to parse arXiv XML response', {
      format: 'xml',
      cause: error instanceof Error ? error : undefined
    });
  }

  return results;
}

/**
 * 提取 XML 标签内容
 */
function extractXmlTag(xml: string, tag: string): string {
  const regex = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
  const match = xml.match(regex);
  return match ? match[1].trim() : '';
}

/**
 * 安全提取 JSON
 * 使用平衡括号匹配，支持嵌套 JSON
 */
export function extractJson<T = unknown>(text: string): JsonExtractionResult<T> {
  // 首先尝试从 markdown 代码块中提取
  const codeBlockMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) {
    text = codeBlockMatch[1].trim();
  }

  // 查找 JSON 对象或数组的起始位置
  const objectStart = text.indexOf('{');
  const arrayStart = text.indexOf('[');

  let startIndex: number;
  let openChar: string;
  let closeChar: string;

  if (objectStart === -1 && arrayStart === -1) {
    return {
      success: false,
      error: 'No JSON object or array found in text'
    };
  }

  if (objectStart === -1) {
    startIndex = arrayStart;
    openChar = '[';
    closeChar = ']';
  } else if (arrayStart === -1) {
    startIndex = objectStart;
    openChar = '{';
    closeChar = '}';
  } else {
    // 选择先出现的
    if (objectStart < arrayStart) {
      startIndex = objectStart;
      openChar = '{';
      closeChar = '}';
    } else {
      startIndex = arrayStart;
      openChar = '[';
      closeChar = ']';
    }
  }

  // 使用平衡括号匹配找到完整的 JSON
  let depth = 0;
  let inString = false;
  let escapeNext = false;
  let endIndex = -1;

  for (let i = startIndex; i < text.length; i++) {
    const char = text[i];

    if (escapeNext) {
      escapeNext = false;
      continue;
    }

    if (char === '\\' && inString) {
      escapeNext = true;
      continue;
    }

    if (char === '"') {
      inString = !inString;
      continue;
    }

    if (inString) {
      continue;
    }

    if (char === openChar || (openChar === '{' && char === '{') || (openChar === '[' && char === '[')) {
      if (char === openChar) depth++;
    } else if (char === closeChar || (closeChar === '}' && char === '}') || (closeChar === ']' && char === ']')) {
      if (char === closeChar) depth--;
      if (depth === 0) {
        endIndex = i;
        break;
      }
    }
  }

  if (endIndex === -1) {
    return {
      success: false,
      error: 'Unbalanced brackets in JSON'
    };
  }

  const jsonStr = text.substring(startIndex, endIndex + 1);

  try {
    const data = JSON.parse(jsonStr) as T;
    return {
      success: true,
      data,
      rawMatch: jsonStr
    };
  } catch (error) {
    return {
      success: false,
      error: `JSON parse error: ${getErrorMessage(error)}`,
      rawMatch: jsonStr
    };
  }
}

/**
 * 带重试的异步函数执行
 * 使用指数退避策略
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  options: RetryOptions = {}
): Promise<T> {
  const opts = { ...DEFAULT_RETRY_OPTIONS, ...options };
  let lastError: Error | undefined;
  let delay = opts.initialDelayMs;

  for (let attempt = 0; attempt <= opts.maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(getErrorMessage(error));

      // 检查是否应该重试
      if (attempt >= opts.maxRetries || !isRetryableError(error)) {
        throw lastError;
      }

      // 等待后重试
      await sleep(delay);
      delay = Math.min(delay * opts.backoffMultiplier, opts.maxDelayMs);
    }
  }

  throw lastError || new Error('Retry failed');
}

/**
 * 带重试的 fetch
 */
export async function fetchWithRetry(
  url: string,
  init?: RequestInit,
  options: RetryOptions = {}
): Promise<Response> {
  return withRetry(async () => {
    const response = await fetch(url, init);

    // 检查是否需要重试的状态码
    if (response.status === 429 || response.status >= 500) {
      throw new ApiCallError(`HTTP ${response.status}`, {
        endpoint: url,
        responseStatus: response.status,
        retryable: true
      });
    }

    if (!response.ok) {
      throw new ApiCallError(`HTTP ${response.status}: ${response.statusText}`, {
        endpoint: url,
        responseStatus: response.status,
        retryable: false
      });
    }

    return response;
  }, options);
}

/**
 * 带超时的 Promise
 */
export async function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number = DEFAULT_TIMEOUT_MS,
  operation?: string
): Promise<T> {
  let timeoutId: ReturnType<typeof setTimeout>;

  const timeoutPromise = new Promise<never>((_, reject) => {
    timeoutId = setTimeout(() => {
      reject(new TimeoutError(
        `Operation timed out after ${timeoutMs}ms${operation ? `: ${operation}` : ''}`,
        { timeoutMs, operation }
      ));
    }, timeoutMs);
  });

  try {
    const result = await Promise.race([promise, timeoutPromise]);
    clearTimeout(timeoutId!);
    return result;
  } catch (error) {
    clearTimeout(timeoutId!);
    throw error;
  }
}

/**
 * 带超时的 Promise.allSettled
 */
export async function promiseAllWithTimeout<T>(
  promises: Promise<T>[],
  timeoutMs: number = DEFAULT_TIMEOUT_MS
): Promise<PromiseSettledResult<T>[]> {
  const wrappedPromises = promises.map(p =>
    withTimeout(p, timeoutMs).then(
      value => ({ status: 'fulfilled' as const, value }),
      reason => ({ status: 'rejected' as const, reason })
    )
  );

  return Promise.all(wrappedPromises);
}

/**
 * 睡眠函数
 */
function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * 安全的字符串截断
 */
export function truncate(str: string, maxLength: number, suffix: string = '...'): string {
  if (str.length <= maxLength) {
    return str;
  }
  return str.substring(0, maxLength - suffix.length) + suffix;
}

/**
 * 标准化标题用于去重
 */
export function normalizeTitle(title: string): string {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9\u4e00-\u9fa5]/g, '') // 保留字母、数字和中文
    .substring(0, 50);
}

/**
 * 从 OpenAlex 反转索引重建摘要文本
 */
export function reconstructAbstract(invertedIndex: Record<string, number[]>): string {
  if (!invertedIndex || typeof invertedIndex !== 'object') return '';

  const words: Array<[number, string]> = [];
  for (const [word, positions] of Object.entries(invertedIndex)) {
    for (const pos of positions) {
      words.push([pos, word]);
    }
  }

  words.sort((a, b) => a[0] - b[0]);
  return words.map(([, word]) => word).join(' ');
}

/**
 * 解析 PubMed XML efetch 响应
 */
export function parsePubMedXml(xml: string): Array<{
  pmid: string;
  title: string;
  authors: string[];
  abstract: string;
  publishDate: string;
  journal?: string;
  doi?: string;
  meshTerms?: string[];
}> {
  const results: Array<{
    pmid: string;
    title: string;
    authors: string[];
    abstract: string;
    publishDate: string;
    journal?: string;
    doi?: string;
    meshTerms?: string[];
  }> = [];

  try {
    const articles = xml.split('<PubmedArticle>').slice(1);

    for (const article of articles) {
      try {
        const pmid = extractXmlTagUtil(article, 'PMID');
        const title = extractXmlTagUtil(article, 'ArticleTitle').replace(/\s+/g, ' ').trim();

        // Extract abstract
        const abstractMatch = article.match(/<Abstract>[\s\S]*?<\/Abstract>/);
        let abstract = '';
        if (abstractMatch) {
          const abstractTexts: string[] = [];
          const textRegex = /<AbstractText[^>]*>([^<]*)<\/AbstractText>/g;
          let match;
          while ((match = textRegex.exec(abstractMatch[0])) !== null) {
            abstractTexts.push(match[1].trim());
          }
          abstract = abstractTexts.join(' ');
        }

        // Extract authors
        const authors: string[] = [];
        const authorRegex = /<Author[^>]*>[\s\S]*?<LastName>([^<]+)<\/LastName>[\s\S]*?<ForeName>([^<]+)<\/ForeName>[\s\S]*?<\/Author>/g;
        let authorMatch;
        while ((authorMatch = authorRegex.exec(article)) !== null) {
          authors.push(`${authorMatch[2].trim()} ${authorMatch[1].trim()}`);
        }

        // Extract date
        const yearMatch = article.match(/<PubDate>[\s\S]*?<Year>(\d{4})<\/Year>/);
        const monthMatch = article.match(/<PubDate>[\s\S]*?<Month>([^<]+)<\/Month>/);
        const year = yearMatch ? yearMatch[1] : '';
        const month = monthMatch ? monthMatch[1] : '';
        const publishDate = month ? `${year}-${month}` : year;

        // Extract journal
        const journal = extractXmlTagUtil(article, 'Title');

        // Extract DOI
        const doiMatch = article.match(/<ArticleId IdType="doi">([^<]+)<\/ArticleId>/);
        const doi = doiMatch ? doiMatch[1] : undefined;

        // Extract MeSH terms
        const meshTerms: string[] = [];
        const meshRegex = /<DescriptorName[^>]*>([^<]+)<\/DescriptorName>/g;
        let meshMatch;
        while ((meshMatch = meshRegex.exec(article)) !== null) {
          meshTerms.push(meshMatch[1].trim());
        }

        results.push({
          pmid,
          title,
          authors,
          abstract,
          publishDate,
          journal: journal || undefined,
          doi,
          meshTerms: meshTerms.length > 0 ? meshTerms : undefined
        });
      } catch {
        continue;
      }
    }
  } catch (error) {
    throw new ParseError('Failed to parse PubMed XML response', {
      format: 'xml',
      cause: error instanceof Error ? error : undefined
    });
  }

  return results;
}

/**
 * XML 标签提取工具函数 (公共版本)
 */
function extractXmlTagUtil(xml: string, tag: string): string {
  const regex = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
  const match = xml.match(regex);
  return match ? match[1].trim() : '';
}

/**
 * Shared Validators - 输入验证函数
 * 提供 CLI 参数和数据验证
 */

import type {
  ValidationResult,
  ValidationError,
  SearchSource,
  SortBy,
  LearningDepth,
  AnalysisMode,
  ReportType,
  SearchCliParams
} from './types';

// 有效值常量
const VALID_PAPER_VIZ_THEMES = ['academic-dark', 'academic-light'] as const;
const VALID_SEARCH_SOURCES: SearchSource[] = [
  'arxiv', 'semantic_scholar', 'web',
  'pubmed', 'crossref', 'openalex', 'dblp',
  'core', 'ieee', 'unpaywall', 'google_scholar'
];
const VALID_SORT_BY: SortBy[] = ['relevance', 'date', 'citations'];
const VALID_LEARNING_DEPTHS: LearningDepth[] = ['beginner', 'intermediate', 'advanced'];
const VALID_ANALYSIS_MODES: AnalysisMode[] = ['quick', 'standard', 'deep'];
const VALID_REPORT_TYPES: ReportType[] = ['daily', 'weekly', 'monthly'];

/**
 * 创建验证结果
 */
function createResult(errors: ValidationError[] = []): ValidationResult {
  return {
    valid: errors.length === 0,
    errors
  };
}

/**
 * 创建验证错误
 */
function createError(field: string, message: string, value?: unknown): ValidationError {
  return { field, message, value };
}

/**
 * 验证数值范围
 */
export function validateNumberRange(
  value: number,
  min: number,
  max: number,
  fieldName: string
): ValidationResult {
  const errors: ValidationError[] = [];

  if (typeof value !== 'number' || isNaN(value)) {
    errors.push(createError(fieldName, `${fieldName} must be a valid number`, value));
  } else if (value < min) {
    errors.push(createError(fieldName, `${fieldName} must be at least ${min}`, value));
  } else if (value > max) {
    errors.push(createError(fieldName, `${fieldName} must be at most ${max}`, value));
  }

  return createResult(errors);
}

/**
 * 验证搜索源
 */
export function validateSearchSource(value: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (!VALID_SEARCH_SOURCES.includes(value as SearchSource)) {
    errors.push(createError(
      'source',
      `Invalid source. Must be one of: ${VALID_SEARCH_SOURCES.join(', ')}`,
      value
    ));
  }

  return createResult(errors);
}

/**
 * 验证排序方式
 */
export function validateSortBy(value: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (!VALID_SORT_BY.includes(value as SortBy)) {
    errors.push(createError(
      'sortBy',
      `Invalid sortBy. Must be one of: ${VALID_SORT_BY.join(', ')}`,
      value
    ));
  }

  return createResult(errors);
}

/**
 * 验证学习深度
 */
export function validateLearningDepth(value: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (!VALID_LEARNING_DEPTHS.includes(value as LearningDepth)) {
    errors.push(createError(
      'depth',
      `Invalid depth. Must be one of: ${VALID_LEARNING_DEPTHS.join(', ')}`,
      value
    ));
  }

  return createResult(errors);
}

/**
 * 验证分析模式
 */
export function validateAnalysisMode(value: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (!VALID_ANALYSIS_MODES.includes(value as AnalysisMode)) {
    errors.push(createError(
      'mode',
      `Invalid mode. Must be one of: ${VALID_ANALYSIS_MODES.join(', ')}`,
      value
    ));
  }

  return createResult(errors);
}

/**
 * 验证报告类型
 */
export function validateReportType(value: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (!VALID_REPORT_TYPES.includes(value as ReportType)) {
    errors.push(createError(
      'type',
      `Invalid type. Must be one of: ${VALID_REPORT_TYPES.join(', ')}`,
      value
    ));
  }

  return createResult(errors);
}

/**
 * 验证非空字符串
 */
export function validateNonEmptyString(value: string, fieldName: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (typeof value !== 'string' || value.trim().length === 0) {
    errors.push(createError(fieldName, `${fieldName} is required and cannot be empty`, value));
  }

  return createResult(errors);
}

/**
 * 验证 URL
 */
export function validateUrl(value: string, fieldName: string = 'url'): ValidationResult {
  const errors: ValidationError[] = [];

  try {
    new URL(value);
  } catch {
    errors.push(createError(fieldName, `${fieldName} must be a valid URL`, value));
  }

  return createResult(errors);
}

/**
 * 验证搜索参数
 */
export function validateSearchParams(params: Partial<SearchCliParams>): ValidationResult {
  const errors: ValidationError[] = [];

  // 验证查询
  if (!params.query || params.query.trim().length === 0) {
    errors.push(createError('query', 'Search query is required'));
  }

  // 验证限制数量
  if (params.limit !== undefined) {
    const limitResult = validateNumberRange(params.limit, 1, 100, 'limit');
    errors.push(...limitResult.errors);
  }

  // 验证搜索源
  if (params.source !== undefined) {
    const sourceResult = validateSearchSource(params.source);
    errors.push(...sourceResult.errors);
  }

  // 验证排序方式
  if (params.sortBy !== undefined) {
    const sortResult = validateSortBy(params.sortBy);
    errors.push(...sortResult.errors);
  }

  return createResult(errors);
}

/**
 * 验证学习参数
 */
export function validateLearnParams(params: {
  concept?: string;
  depth?: string;
}): ValidationResult {
  const errors: ValidationError[] = [];

  // 验证概念
  if (!params.concept || params.concept.trim().length === 0) {
    errors.push(createError('concept', 'Concept is required'));
  }

  // 验证深度
  if (params.depth !== undefined) {
    const depthResult = validateLearningDepth(params.depth);
    errors.push(...depthResult.errors);
  }

  return createResult(errors);
}

/**
 * 验证检测参数
 */
export function validateDetectParams(params: {
  domain?: string;
}): ValidationResult {
  const errors: ValidationError[] = [];

  // 验证领域
  if (!params.domain || params.domain.trim().length === 0) {
    errors.push(createError('domain', 'Domain is required'));
  }

  return createResult(errors);
}

/**
 * 验证分析参数
 */
export function validateAnalyzeParams(params: {
  url?: string;
  mode?: string;
}): ValidationResult {
  const errors: ValidationError[] = [];

  // 验证 URL
  if (!params.url) {
    errors.push(createError('url', 'Paper URL is required'));
  } else {
    const urlResult = validateUrl(params.url);
    errors.push(...urlResult.errors);
  }

  // 验证模式
  if (params.mode !== undefined) {
    const modeResult = validateAnalysisMode(params.mode);
    errors.push(...modeResult.errors);
  }

  return createResult(errors);
}

/**
 * 验证图谱参数
 */
export function validateGraphParams(params: {
  concepts?: string[];
}): ValidationResult {
  const errors: ValidationError[] = [];

  // 验证概念列表
  if (!params.concepts || params.concepts.length < 2) {
    errors.push(createError('concepts', 'At least 2 concepts are required'));
  }

  return createResult(errors);
}

/**
 * 格式化验证错误为可读字符串
 */
export function formatValidationErrors(errors: ValidationError[]): string {
  if (errors.length === 0) {
    return '';
  }

  return errors
    .map(e => `  - ${e.field}: ${e.message}${e.value !== undefined ? ` (got: ${JSON.stringify(e.value)})` : ''}`)
    .join('\n');
}

/**
 * 合并多个验证结果
 */
export function mergeValidationResults(...results: ValidationResult[]): ValidationResult {
  const allErrors: ValidationError[] = [];

  for (const result of results) {
    allErrors.push(...result.errors);
  }

  return createResult(allErrors);
}

/**
 * 类型守卫：检查是否为有效的搜索源
 */
export function isValidSearchSource(value: unknown): value is SearchSource {
  return typeof value === 'string' && VALID_SEARCH_SOURCES.includes(value as SearchSource);
}

/**
 * 类型守卫：检查是否为有效的排序方式
 */
export function isValidSortBy(value: unknown): value is SortBy {
  return typeof value === 'string' && VALID_SORT_BY.includes(value as SortBy);
}

/**
 * 类型守卫：检查是否为有效的学习深度
 */
export function isValidLearningDepth(value: unknown): value is LearningDepth {
  return typeof value === 'string' && VALID_LEARNING_DEPTHS.includes(value as LearningDepth);
}

/**
 * 类型守卫：检查是否为有效的分析模式
 */
export function isValidAnalysisMode(value: unknown): value is AnalysisMode {
  return typeof value === 'string' && VALID_ANALYSIS_MODES.includes(value as AnalysisMode);
}

/**
 * 类型守卫：检查是否为有效的报告类型
 */
export function isValidReportType(value: unknown): value is ReportType {
  return typeof value === 'string' && VALID_REPORT_TYPES.includes(value as ReportType);
}

/**
 * 验证 PDF 下载参数
 */
export function validatePdfDownloadParams(params: {
  query?: string;
  limit?: number;
  outputDir?: string;
}): ValidationResult {
  const errors: ValidationError[] = [];

  if (!params.query || params.query.trim().length === 0) {
    errors.push(createError('query', 'Search query is required for PDF download'));
  }

  if (params.limit !== undefined) {
    const limitResult = validateNumberRange(params.limit, 1, 50, 'limit');
    errors.push(...limitResult.errors);
  }

  return createResult(errors);
}

/**
 * 验证论文可视化参数
 */
export function validatePaperVizParams(params: {
  url?: string;
  mode?: string;
  theme?: string;
}): ValidationResult {
  const errors: ValidationError[] = [];

  if (!params.url) {
    errors.push(createError('url', 'Paper URL is required'));
  } else {
    const urlResult = validateUrl(params.url);
    errors.push(...urlResult.errors);
  }

  if (params.mode !== undefined) {
    const modeResult = validateAnalysisMode(params.mode);
    errors.push(...modeResult.errors);
  }

  if (params.theme !== undefined && !VALID_PAPER_VIZ_THEMES.includes(params.theme as typeof VALID_PAPER_VIZ_THEMES[number])) {
    errors.push(createError('theme', `Invalid theme. Must be one of: ${VALID_PAPER_VIZ_THEMES.join(', ')}`, params.theme));
  }

  return createResult(errors);
}

/**
 * 验证交互式图谱参数
 */
export function validateGraphInteractiveParams(params: {
  graphName?: string;
}): ValidationResult {
  const errors: ValidationError[] = [];

  if (!params.graphName || params.graphName.trim().length === 0) {
    errors.push(createError('graphName', 'Graph name is required'));
  }

  return createResult(errors);
}

